descriptor.templateCss:
.sp-card {
    font-family: Roboto, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, sans-serif;
    width: 100%;
    height: 100%;
    min-height: 0;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    color: #24364b;
    background: #ffffff;
    border: 1px solid #dbe5ef;
    border-radius: 14px;
    box-shadow: 0 1px 3px rgba(12, 31, 53, .07);
}

.sp-head {
    flex: 0 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 14px 16px;
    border-bottom: 1px solid #e7eef6;
    background: #fbfdff;
}

.sp-title-wrap {
    min-width: 0;
}

.sp-title {
    font-size: 13px;
    line-height: 1.25;
    font-weight: 800;
    color: #22384f;
    text-transform: uppercase;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.sp-sub {
    margin-top: 3px;
    font-size: 11px;
    line-height: 1.35;
    font-weight: 600;
    color: #7c92a8;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.sp-chip {
    flex: 0 0 auto;
    max-width: 44%;
    padding: 5px 9px;
    border-radius: 999px;
    border: 1px solid #cfe0ef;
    background: #eef6fd;
    color: #275f8f;
    font-size: 11px;
    line-height: 1.2;
    font-weight: 800;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.sp-grid {
    flex: 1 1 auto;
    min-height: 0;
    overflow: auto;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    grid-auto-rows: minmax(82px, auto);
    gap: 10px;
    padding: 12px;
    align-content: start;
    background: #f6f9fc;
}

.sp-tile {
    position: relative;
    min-width: 0;
    min-height: 82px;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    gap: 8px;
    padding: 11px 12px;
    overflow: hidden;
    border: 1px solid #e3ebf3;
    border-radius: 12px;
    background: #ffffff;
    box-shadow: inset 0 3px 0 #9aaec1;
}

.sp-label {
    min-width: 0;
    font-size: 11px;
    line-height: 1.25;
    font-weight: 800;
    color: #667b91;
    text-transform: uppercase;
    word-break: break-word;
}

.sp-val {
    min-width: 0;
    font-size: 28px;
    line-height: 1;
    font-weight: 900;
    color: #22384f;
    font-variant-numeric: tabular-nums;
}

.sp-tile.active {
    box-shadow: inset 0 3px 0 #2f80ed;
}

.sp-tile.cleared {
    box-shadow: inset 0 3px 0 #2eaf62;
}

.sp-tile.unack {
    box-shadow: inset 0 3px 0 #f59e0b;
}

.sp-tile.ack {
    box-shadow: inset 0 3px 0 #607d8b;
}

.sp-tile.critical {
    box-shadow: inset 0 3px 0 #d32f2f;
}

.sp-tile.major {
    box-shadow: inset 0 3px 0 #ef6c00;
}

.sp-tile.warning {
    box-shadow: inset 0 3px 0 #f9a825;
}

.sp-tile.minor {
    box-shadow: inset 0 3px 0 #26a69a;
}

.sp-tile.indet {
    box-shadow: inset 0 3px 0 #7e57c2;
}

.sp-tile.critical .sp-val,
.sp-tile.major .sp-val {
    color: #b3261e;
}

.sp-tile.warning .sp-val,
.sp-tile.unack .sp-val {
    color: #9a6500;
}

.sp-tile.cleared .sp-val {
    color: #1f7a43;
}

.sp-empty {
    grid-column: 1 / -1;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 120px;
    padding: 20px;
    color: #7c92a8;
    font-size: 13px;
    font-weight: 600;
    text-align: center;
    border: 1px dashed #cfe0ef;
    border-radius: 12px;
    background: #ffffff;
}

@media (max-width: 1100px) {
    .sp-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 560px) {
    .sp-head {
        align-items: flex-start;
        flex-direction: column;
    }

    .sp-chip {
        max-width: 100%;
    }

    .sp-grid {
        grid-template-columns: 1fr;
    }
}

.sp-tile {
    appearance: none;
    text-align: left;
    cursor: pointer;
}

.sp-tile:focus-visible {
    outline: 2px solid #1e88e5;
    outline-offset: 2px;
}

.sp-tile.selected {
    border-color: #1e88e5;
    background: #f3f9ff;
    box-shadow: inset 0 3px 0 #1e88e5, 0 0 0 2px rgba(30, 136, 229, .18);
}

descriptor.controllerScript:
self.onInit = function() {
    var root = self.ctx && self.ctx.$container && self.ctx.$container[0];
    if (!root) return;
    var titleEl = root.querySelector('#sp-title'),
        subEl = root.querySelector('#sp-sub'),
        chipEl = root.querySelector('#sp-chip'),
        grid = root.querySelector('#sp-grid');
    var selectedKey = 'ALL';

    var pageLink = self.ctx.pageLink(1024);
    var wc = self.ctx.widgetConfig || {};
    pageLink.typeList = wc.alarmTypeList;
    pageLink.statusList = wc.alarmStatusList;
    pageLink.severityList = wc.alarmSeverityList;
    pageLink.searchPropagatedAlarms = wc.searchPropagatedAlarms;
    self.ctx.defaultSubscription.subscribeForAlarms(pageLink, null);

    function esc(value) {
        return String(value == null ? '' : value)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#39;');
    }

    function tile(cls, label, val, filterType, filterValue) {
        var key = filterType + ':' + filterValue;
        var selected = selectedKey === key;
        return '<button type="button" class="sp-tile ' + cls + (selected ? ' selected' : '') + '" data-filter-type="' +
            esc(filterType) + '" data-filter-value="' + esc(filterValue) + '" aria-pressed="' + selected + '"><div class="sp-label">' +
            esc(label) + '</div><div class="sp-val">' + esc(val) + '</div></button>';
    }

    function publishFilter(type, value) {
        var detail = { source: 'hvac_alarms_counter', status: 'ALL', severity: 'ALL' };
        if (type === 'status') detail.status = value;
        if (type === 'severity') detail.severity = value;
        try {
            window.dispatchEvent(new CustomEvent('HVAC_ALARMS_COUNTER_FILTER', { detail: detail }));
        } catch (e) {}
    }

    function countAlarms(arr) {
        var s = { total: 0, active: 0, cleared: 0, unack: 0, ack: 0, critical: 0, major: 0, warning: 0, minor: 0, indet: 0 };
        for (var i = 0; i < arr.length; i++) {
            var a = arr[i];
            if (!a || typeof a !== 'object') continue;
            s.total++;
            var st = String(a.status || '').toUpperCase();
            var sv = String(a.severity || '').toUpperCase();
            if (st.indexOf('ACTIVE') !== -1) s.active++;
            if (st.indexOf('CLEARED') !== -1) s.cleared++;
            if (st.indexOf('UNACK') !== -1) s.unack++;
            if (st.indexOf('ACK') !== -1 && st.indexOf('UNACK') === -1) s.ack++;
            if (sv === 'CRITICAL') s.critical++;
            else if (sv === 'MAJOR') s.major++;
            else if (sv === 'WARNING') s.warning++;
            else if (sv === 'MINOR') s.minor++;
            else if (sv === 'INDETERMINATE') s.indet++;
        }
        return s;
    }

    function render() {
        if (!grid) return;
        var ctx = self.ctx;
        if (titleEl) titleEl.textContent = String((ctx.settings && ctx.settings.chartTitle) || 'HVAC Alarms Counter');
        if (subEl) subEl.textContent = String((ctx.settings && ctx.settings.chartSubtitle) || 'Live totals for current scope');
        var alarms = ctx.defaultSubscription && ctx.defaultSubscription.alarms && ctx.defaultSubscription.alarms.data;
        var s = { total: 0, active: 0, cleared: 0, unack: 0, ack: 0, critical: 0, major: 0, warning: 0, minor: 0, indet: 0 };
        if (Array.isArray(alarms) && alarms.length) s = countAlarms(alarms);
        if (chipEl) chipEl.textContent = s.total + ' records';
        grid.innerHTML = tile('active', 'Active', s.active, 'status', 'ACTIVE') +
            tile('cleared', 'Cleared', s.cleared, 'status', 'CLEARED') +
            tile('unack', 'Unacknowledged', s.unack, 'status', 'UNACK') +
            tile('ack', 'Acknowledged', s.ack, 'status', 'ACK') +
            tile('critical', 'Critical', s.critical, 'severity', 'CRITICAL') +
            tile('major', 'Major', s.major, 'severity', 'MAJOR') +
            tile('warning', 'Warning', s.warning, 'severity', 'WARNING') +
            tile('minor', 'Minor', s.minor, 'severity', 'MINOR') +
            tile('indet', 'Indeterminate', s.indet, 'severity', 'INDETERMINATE');
    }

    function onClick(event) {
        var tileEl = event.target.closest('.sp-tile[data-filter-type]');
        if (!tileEl || !grid || !grid.contains(tileEl)) return;
        var type = tileEl.getAttribute('data-filter-type') || 'status';
        var value = tileEl.getAttribute('data-filter-value') || 'ALL';
        var key = type + ':' + value;
        if (selectedKey === key) {
            selectedKey = 'ALL';
            publishFilter('status', 'ALL');
        } else {
            selectedKey = key;
            publishFilter(type, value);
        }
        render();
    }

    if (grid) grid.addEventListener('click', onClick);
    self.__state = { render: render, onClick: onClick };
    self.onDataUpdated = function() { if (self.__state) self.__state.render(); };
    self.onResize = function() { if (self.__state) self.__state.render(); };
    self.onDestroy = function() {
        if (grid && self.__state && self.__state.onClick) grid.removeEventListener('click', self.__state.onClick);
        self.__state = null;
    };
    render();
};

self.typeParameters = function() {
    return { maxDatasources: 0, maxDataKeys: 0, dataKeysOptional: true, hasDataPageLink: true, singleEntity: false, warnOnPageDataOverflow: false };
};
